        cap: '1人を引き上げる場合（30人未満の事業場／30人以上の事業場）＝50円コース40万／30万円、70円コース50万／40万円、90円コース100万／90万円。引き上げる人数が多いほど上限が上がり、90円コースで8人以上なら450万円。最高額の600万円は特例事業者が10人以上を引き上げる場合に限られます',
