        'パソコン・タブレット・スマートフォンは原則として対象外ですが、POSレジや会計給与システムなど、特定の業務専用のシステムを動かす目的だとはっきりしている場合は、対象になることがあります。対象外の自動車は「特種用途自動車（8ナンバー・福祉車両など）以外」で、特種用途自動車は対象になります。また、[[物価高騰等要件（最近6か月間平均の売上高総利益率または売上高営業利益率が前年同期比3％ポイント以上低下）を満たす特例事業者は、パソコン・タブレット・スマートフォン（新規購入に限る）も対象経費になります]]（交付要領別紙3注8）。',
        '委託費のうち、就業規則の作成・改正と賃金制度の整備にかかる費用は対象になりません。経営コンサルティング経費も、人員削減や労働条件の引き下げを内容とするものは対象外です。法令等で義務づけられた措置の整備費用や、事業を実施するうえで必須となる資格の取得費用も対象外です（交付要領別紙3注7⑤）。',
        // 交付要領別紙3注1・2・6（2026-08-06 4回目監査で確認）
        '経費区分ごとの細目上限もあります。謝金は1回10万円まで・回数は5回まで（注1）。旅費は公共交通機関の実費のみが対象で、グリーン車などの割増運賃は対象外です（上限額そのものの定めはありません、注2）。リース・ローン契約は契約時点から3年分までが対象です（注6）。',
        // 交付要綱第4条第4項第四号（2026-08-06 4回目監査で確認）
        '[[申請書の提出日から過去5年以内に、この助成金またはほかの補助金等で交付決定の取消しその他これに準ずる処分を受けている]]場合は、不交付になります。',
        '免税事業者などは消費税を含めた額で申請できる場合があります（その場合の助成額は、この試算より少し多くなります）。委託費のうち、就業規則の作成・改正と賃金制度の整備にかかる費用は対象になりません。',
        // Q&A問47
        'ここで賃金引上げの対象にした人は、キャリアアップ助成金（賃金規定等改定コース）の対象人数には数えられません。',
