    //
    // どのコースにも共通する大前提：
    //   取組を始める前日までに「キャリアアップ計画」を管轄労働局へ出しておくこと。
    //   これを落とすと、あとから何をしても支給されない。
    // ================================================================

    // ---- 正社員化コース ----
    // 支給要領1005：有期→正規 中小40万円／大企業30万円（支給対象期1期あたり）
    //               無期→正規 中小20万円／大企業15万円（同）
    //   重点支援対象者は2期、それ以外は1期。だから ご案内 の表（重点支援は80万／40万、
    //   それ以外は40万／20万）と一致する。
    //   加算（1適用事業所あたり）：転換制度の新設20万（大15万）／多様な正社員制度の新設
    //   40万（大30万）／情報公表20万（大15万）
