        note: '1回目：30万円×3区分・加算なしは要領0302aと一致。常時10人未満は就業規則が無くても明文化と周知で対象になること（0301a イ）、失効年休を積み立てる制度は使えること（0301a ニ(ｲ)）、短時間勤務の要件（0301a ニ(ﾛ)）を追加した。月経は無給だと労基法68条の生理休暇にすぎず対象外という書き分けは要領0201b イ・Q&A 問8/問9のとおりで正しいと確認された。'
