        schedule: '通年受付。申請期限は<strong>対象のスタッフの制度利用が合計5日（回）を経過する日の翌日から2か月以内</strong>です（例：5月13日に使い始めて11月12日に5日目を経過したら、11月13日から1月12日までが申請期間）。<strong>制度の利用は、使い始めた日から1年以内に5日（回）を満たす</strong>必要があります。時間単位で使うこともできますが、5日（回）に分けて使う必要があります（同じ日に同じ制度を2回使っても1回、同じ日に別の制度を使えばそれぞれ1回と数えます）。郵送は消印日ではなく<strong>労働局に届いた日</strong>で判定されます',
