    // ---- 育休中等業務代替支援コース ----
    // 手引き p.95／支給要領（令和8年4月8日改正）0302・0303
    //   [1]手当支給等（育児休業）… 業務体制整備経費6万（育休1か月未満は2万／労務コンサル
    //                              委託なら20万）＋ 手当総額の3/4（月10万円上限・24か月分まで）
    //   [2]手当支給等（短時間勤務）… 業務体制整備経費3万（コンサル20万）＋ 手当総額の3/4
    //                                （月3万円上限・子が3歳になるまで）
    //   [3]新規雇用（育児休業）… 代替した期間に応じた定額 9／13.5／27／45／67.5／81万
    //   プラチナくるみん認定なら 手当は4/5、新規雇用は 11／16.5／33／55／82.5／99万
    //   有期雇用労働者加算10万・情報公表加算2万／1事業主1年度で[1]〜[3]合計10人まで
    //
