    //   ①人材育成訓練 有期     70%        +15%           －
    //   ②認定実習併用職業訓練   45%(30%)   +15%(+15%)     20万(11万) +5万(3万)
    //   ③有期実習型訓練        75%        +25%           10万( 9万) +3万(3万)
    //   ④中高年齢者実習型訓練   60%(45%)   +15%(+15%)     10万( 9万) +3万(3万)   ← 令和8年度新設
    //   賃金助成（1人1時間あたり）800円(400円)、賃金要件等で +200円(+100円)
    //
    // 1労働者1訓練あたりの経費助成限度額（ご案内 p.15）中小（大企業）
    //   10時間以上100時間未満 15万(10万)／100時間以上200時間未満 30万(20万)／200時間以上 50万(30万)
    //   ※eラーニング・通信制は一律「10時間以上100時間未満」の区分になる
    //   ※賃金助成の対象時間は1人1訓練あたり1,200時間まで（専門実践教育訓練は1,600時間）
    //   ※1事業所の一の年度あたりの支給限度額は1,000万円
    // ================================================================
