        note: '1回目：助成率24通り・OJT12通り・限度額・1,200時間・1,000万円・計画届の期限は一次資料と一致。'
          + '賃金助成を「訓練時間×人数」で出していたのが最大の誤りで、対象は所定労働時間内に受講した分だけ'
