        '[[訓練を受ける人は、雇用保険の被保険者でなければなりません]]。[[業務委託や面貸しのスタイリストは、受講させても1円も出ません]]。[[同居の親族も原則として雇用保険の適用除外]]なので、家族だけで営んでいるサロンでは対象者がいないことがあります（試用期間中でも週20時間以上・31日以上の見込みがあれば被保険者です）。',
        '[[訓練の経費をスタッフに一部でも負担させると、賃金助成も含めて全額が不支給になります]]（ご案内 p.42）。メーカー講習やセミナー費用をスタッフと折半する形は対象外です。[[事業主以外（親会社など）が負担している分、あとから返金やキャッシュバックを受けた分も経費助成の対象外]]です。',
        '計画届を出す日までに、[[職業能力開発推進者の選任]]と[[事業内職業能力開発計画の策定・周知]]（有期実習型訓練を除く）、[[キャリアコンサルティングの機会確保を就業規則等に定めること]]（「入社から3年ごとに」のように時期を明記し、費用は事業主が全額負担）が終わっている必要があります（要領06011 ヌ）。',
