        note: '1回目：表1・表2（3表36セル）・表3・割増賃金率加算・補助率の境界・1,000円未満切り捨ては'
          + '交付要綱／支給要領のPDFから独立に再抽出して突合し、一致を確認。'
          + '最大の誤りは助成対象経費の上限（表3）の当て方で、経費の合計に1回だけ上限を当てていたため、'
