        schedule: '令和8年度は2026年4月13日（月）に受付が始まりました。交付申請の締切は2026年11月30日（月）午後5時、事業を終える期限は2027年1月31日（日）、支給申請は事業実施予定期間の終了から30日後か2027年2月5日（金）のいずれか早い日です。郵送は締切当日の消印有効、窓口と電子申請（Jグランツ）は当日17時まで（支給申請の電子申請だけは当日23時59分まで）。ただし申請パンフレットは締切を「必着」と書いているので、余裕をもって出してください',
