        note: '通常枠2/3・賃上げ枠4/5、通常枠の上限はISO14001認証取得の有無で50万円/100万円に分かれる（賃上げ枠は一律100万円）ことをPDF本文で確認。パソコン・タブレット・会計ソフト等の汎用転用可能設備は明確に対象外。'
