            { key: 'wage', label: '賃上げ枠', capKey: 'wage|no', capText: '100万円', wageRequired: true, desc: '対象期間で従業員の給与支給総額を3%以上増やす方針を、従業員代表の署名等がある書面で示すことが必要' }
