          help: 'ソフトウェアの購入・ライセンス料、初期設定・カスタマイズ料、情報セキュリティ機器、キャッシュレス端末、テレワーク関連機器等の購入・賃借料が対象です。[[既に導入済みのソフト・機器の増設・改修・更新・入替えは対象外]]です。ソフトウェア導入に伴い最低限必要な汎用機器（パソコン等）は、対象経費①〜③合計額の1/2または20万円の少ないほうを上限に別枠で算入できます。'
