    // 出典：三鷹商工会中小企業等産業活性化補助金交付要綱（令和8年2月1日施行）
    //   https://www.mitaka-s.jp/docs/2026012000010/file_contents/youkou.pdf （2026-08-06 確認）
    // ================================================================
    tokyo_mitaka_sangyo: {
      kind: 'hojo',
      source: {
        label: '三鷹商工会中小企業等産業活性化補助金交付要綱',
        url: 'https://www.mitaka-s.jp/docs/2026012000010/file_contents/youkou.pdf',
        checked: '2026-08-06 JST'
      },
      review: {
        reviewer: 'shindanshi',
        date: '2026-08-06',
        result: '調査担当と独立検証担当が交付要綱の別表・条文本体を突合し、補助率・上限額とも一致を確認',
        note: '現状サイトに記載されていた「創業者・事業承継者向けは補助率10/10」という記載は、交付要綱・募集案内のいずれにも見当たらず、独立検証担当が条文本体（第1条〜第15条・附則、別表第2）を画像化してまで確認したが根拠を発見できなかった。実在しない可能性が高いため、この試算・index.html双方から削除した。また確認時点（2026-08-06）で三鷹商工会の公式ページには「【募集終了】」の表示があり、成長投資支援枠の延長募集も終了済みで、令和8年度は全枠で新規申請を受け付けていない。'
      },
      status: {
        state: 'closed',
        text: '令和8年度は全枠で募集を終了しています（成長投資支援枠の延長募集［〜7月31日］も終了済み）。次回募集の時期は三鷹商工会の公式ページからは判断できず、未定です（2026年8月6日時点）。'
      },
      intro: '募集終了中のため次回募集に向けた金額の目安としてご覧ください。枠により補助率・上限額が異なります。',
      top: {
        rate: '成長投資支援枠1/2以内（対象経費100万円以上が条件）／グリーン・レジリエンス・デジタル枠2/3以内／一般枠原則1/2以内（研究開発調査費のみ2/3以内）',
        cap: '成長投資支援枠300万円／グリーン・レジリエンス・デジタル・一般枠は経費区分ごとに上限30万円',
        schedule: '令和8年度は全枠で募集終了。次回募集の時期は未定（成長投資支援枠の延長募集も2026年7月31日で終了済み）',
        capKey: 'seicho',
        capText: '300万円',
        tracks: {
          default: 'seicho',
          options: [
            { key: 'seicho', label: '成長投資支援枠', capKey: 'seicho', capText: '300万円（対象経費100万円以上が条件）', wageRequired: false, desc: '労働生産性を年3%以上向上させる計画に基づく設備投資' },
            { key: 'kankyo', label: 'グリーン・レジリエンス・デジタル枠', capKey: 'kankyo', capText: '経費区分ごとに上限30万円', wageRequired: false, desc: '' },
            { key: 'ippan', label: '一般枠', capKey: 'ippan', capText: '経費区分ごとに上限30万円（研究開発調査費のみ2/3以内）', wageRequired: false, desc: '' }
          ]
        }
      },
      questions: [
        {
          id: 'waku', type: 'choice', label: '使う枠', def: 'seicho',
          options: [
            { v: 'seicho', t: '成長投資支援枠', s: '成長投資支援枠' },
            { v: 'kankyo', t: 'グリーン・レジリエンス・デジタル枠', s: 'グリーン等の枠' },
            { v: 'ippan', t: '一般枠', s: '一般枠' }
          ],
          help: '成長投資支援枠は[[労働生産性を年3%以上向上させる計画に基づく機械備品・ソフトウェア等への投資]]が対象で、[[経費全体が100万円以上]]必要です。一般枠は「新製品・新技術の研究・開発調査費」のみ補助率2/3、それ以外の経費区分は1/2です（この試算では簡略化のため一般枠は1/2で計算します）。'
        },
        {
          id: 'cost', type: 'number', label: '対象経費（税抜）', unit: '万円',
          min: 0, max: 300, step: 5, def: 50,
          help: '機械・備品の購入費、店舗レイアウト変更等工事費、ソフトウェア・情報システム費、研究開発調査費、工業所有権取得費、研修・専門家助言費、広告宣伝費が対象です（成長投資支援枠は機械備品・ソフトウェア等への投資に限定）。'
        }
      ],
      calc: {
        type: 'expense_rate', expenseQ: 'cost',
        blocks: [
          {
            when: { all: [{ q: 'waku', eq: 'seicho' }, { q: 'cost', lt: 100 }] },
            message: '成長投資支援枠は[[対象経費が100万円以上]]でないと申請できません。それ未満の場合はグリーン・レジリエンス・デジタル枠か一般枠をご検討ください。'
          }
        ],
        rate: { axes: [{ q: 'waku' }], values: { seicho: 1 / 2, kankyo: 2 / 3, ippan: 1 / 2 } },
        cap: { axes: [{ q: 'waku' }], values: { seicho: 300, kankyo: 30, ippan: 30 } }
      },
      notes: [
        '[[令和8年度は全枠で募集を終了しています]]。次回募集の時期は未定です。',
        '現状サイト等で見かける「創業者・事業承継者向けは補助率10/10」という情報は、[[交付要綱・募集案内のいずれにも根拠が見当たらず、実在を確認できませんでした]]。'
      ],
      notesMore: [
        'グリーン・レジリエンス・デジタル枠・一般枠は、経費区分ごとに下限があります（機械備品・店舗工事・ソフトウェア・広告宣伝は各10万円以上、研修・専門家助言は5万円以上、研究開発調査・工業所有権取得は下限の定めなし）。この試算では区分をまとめて計算しているため、実際の申請では区分ごとの下限にご注意ください。',
        '対象は[[三鷹市内で継続して事業を営む中小企業者等]]（NPO法人・一部の公益法人等含む）です。過去に本補助金の交付を受け「前年度と類似した補助事業」を行う場合は対象外です。'
      ]
    },

