        note: '制度は【1】働く環境整備事業【2】DX推進事業【3】環境配慮加算（【1】か【2】申請時のみ追加可）の3メニューで構成され、全体上限は法人25万円・個人15万円。試算は、従業員がいない個人事業主（一人サロン）も対象になる【2】DX推進事業のみを扱う（【1】は「従業員等がいない個人事業主」が対象外になる点が試算の入力だけでは判定しづらいため）。【1】【3】はnotesMoreで案内する。'
