      status: { state: 'open', text: '申請期間は2026年4月1日〜2027年3月31日です（随時受付、予算がなくなり次第終了。必ず事業開始前に交付申請すること。2026年8月6日時点）。' },
      intro: 'デジタル化により生産性・業務プロセスを改善する取組の経費が対象です（DX推進事業）。',
