          min: 0, max: 20, step: 1, def: 10,
          help: '機械装置費、システム構築費、技術導入費（知的財産権等の導入経費）、運搬料、原材料費、専門家経費、外注費が対象です。[[パソコン・タブレット・プリンタ・スマートフォン等、汎用性が高い製品のみの購入は対象外]]です。'
